// Runs on the NIC e-way bill "Generated By Others" report page
// (https://ewaybillgst.gov.in/Reports/... - reached from the "e-Invoice
// Portal" > "Generated By Others" screen). This is the inward-supply report:
// bills mills/suppliers generated for goods coming to JK India, which is
// what the app's purchase-reconciliation logic actually needs.
//
// This is intentionally scoped to the #ListOthtable table only ("List
// Others"). The government site's "Outward Supplies" report lives at the
// same /Reports/CommomReport.aspx path (just a different ?id= value), and
// Chrome's extension match rules can't filter on query strings - so instead
// of matching by URL, we look for this specific table by its id and do
// nothing at all if it isn't present. That keeps this scraper from ever
// picking up Outward Supplies data if that report happens to be open too.
//
// Every POLL_INTERVAL_MS it reads the EWB No column from the table and
// stores newly-seen numbers in chrome.storage.local. It does NOT touch the
// government page in any other way, and does NOT log in or refresh the
// session itself - it relies on the existing auto-refresh extension /
// manual refresh to keep the table current.

const POLL_INTERVAL_MS = 4 * 60 * 1000;
const STORAGE_KEY = 'jkEwayBill_scrapedNumbers';
const TABLE_ID = 'ListOthtable'; // "Generated By Others" report only.

function getTargetTable() {
  return document.getElementById(TABLE_ID);
}

// This report is a DataTable that only renders the CURRENT page's rows into
// the DOM (default 10/page) - it does not keep every page loaded at once.
// Rather than clicking through every page each cycle, switch the "Show N
// entries" control to its largest option (or "All") once, so every row for
// the selected date sits in the DOM at the same time and a single scrape
// catches all of them.
function ensureMaxPageSize(table) {
  const wrapper = table.closest(`#${TABLE_ID}_wrapper`) || document;
  const select = wrapper.querySelector('.dataTables_length select');
  if (!select) return false;

  const options = Array.from(select.options);
  const allOption = options.find((o) => o.value === '-1' || /all/i.test(o.textContent));
  const best =
    allOption ||
    options.reduce((max, o) => (Number(o.value) > Number(max.value) ? o : max), options[0]);

  if (select.value === best.value) return false; // Already showing everything.

  select.value = best.value;
  select.dispatchEvent(new Event('change', { bubbles: true }));
  console.log(
    `[JK EWayBill Scraper] Set "Show entries" to "${best.textContent}" so all rows load on one page.`
  );
  return true;
}

function scrapeEwbNumbers(table) {
  const cells = table.querySelectorAll('td.sorting_1');
  const numbers = [];
  cells.forEach((cell) => {
    // The number sits alongside a <br> and a date span in this report's
    // cell, so pull out the leading 12-digit run rather than requiring the
    // whole cell text to be exactly the number.
    const match = cell.textContent.trim().match(/\d{12}/);
    if (match) {
      numbers.push(match[0]);
    }
  });
  return numbers;
}

async function pollAndStore() {
  try {
    const table = getTargetTable();
    if (!table) return; // Not the "Generated By Others" report - do nothing.

    const pageSizeChanged = ensureMaxPageSize(table);
    if (pageSizeChanged) {
      // Table is about to redraw with every row; give it a moment before scraping.
      await new Promise((resolve) => setTimeout(resolve, 800));
    }

    const numbers = scrapeEwbNumbers(table);
    if (numbers.length === 0) return;

    const stored = await chrome.storage.local.get(STORAGE_KEY);
    const existing = new Set(stored[STORAGE_KEY] || []);
    const merged = new Set([...existing, ...numbers]);

    await chrome.storage.local.set({ [STORAGE_KEY]: Array.from(merged) });
    console.log(
      `[JK EWayBill Scraper] Found ${numbers.length} EWB no(s) on page, ${merged.size} total pending for import.`
    );
  } catch (err) {
    console.error('[JK EWayBill Scraper] Failed to scrape/store:', err);
  }
}

// Initial scrape in case the page is already loaded.
pollAndStore();

// Re-scrape every 4 minutes.
setInterval(pollAndStore, POLL_INTERVAL_MS);

// Also re-scrape whenever the target table redraws - covers a manual F5 by a
// user and any refresh triggered by the existing auto-refresh extension,
// without waiting for the next 4-minute tick. Uses a body-level observer
// since the table (and its id) may not exist yet at script-injection time,
// e.g. if the user hasn't navigated to this specific report yet.
const bodyObserver = new MutationObserver(() => pollAndStore());
bodyObserver.observe(document.body, { childList: true, subtree: true });
